import sqlite3

def reserve_stock(conn: sqlite3.Connection, product_id: str, quantity: int) -> None:
    with conn:  # transaction : commit automatique, rollback si exception
        cursor = conn.execute(
            "SELECT stock FROM products WHERE id = ?", (product_id,)
        )
        current_stock = cursor.fetchone()[0]
        if current_stock < quantity:
            raise ValueError(f"Stock insuffisant pour {product_id}")
        conn.execute(
            "UPDATE products SET stock = stock - ? WHERE id = ?",
            (quantity, product_id),
        )
